System.register("chunks:///_virtual/quests.json",[],(function(e){return{execute:function(){e("default",{version:2,quests:[{id:"letter-tide",title:"Письмо с прилива",description:"Путник, если ты читаешь это — остров ещё держится над водой. Держись чаек и не смотри вниз слишком долго.\n\n— К.",repeatable:!0,weight:1,reward:{type:"story"}},{id:"craft-bed",title:"Кровать на песке",description:"Сначала найди чертёж — чайки таскают бумагу, как рыбу. Потом доски и верёвки. Сколоти кровать: с неё можно стартовать выше скучных нижних метров.\n\n— К.",repeatable:!1,weight:3,goal:{type:"craft",blueprintId:"bed",requireBlueprint:!0,recipe:{coins:50,items:[{id:"plank",count:6},{id:"rope",count:2}]}},reward:{type:"island",blueprintId:"bed"}},{id:"craft-wardrobe",title:"Платяной шкаф",description:"Остров гол, как ты после шторма. Найди чертёж шкафа, собери лес и верёвки. Когда шкаф встанет, чайки начнут носить выкройки одежды.\n\n— К.",repeatable:!1,weight:2,goal:{type:"craft",blueprintId:"wardrobe",requireBlueprint:!0,recipe:{coins:50,items:[{id:"plank",count:10},{id:"rope",count:5}]}},reward:{type:"island",blueprintId:"wardrobe"}},{id:"craft-slots",title:"Игральный автомат",description:"Удача — такая же валюта, как доски. Достань чертёж автомата и сколоти его. Дальше — монета в щель, и что выпадет, то твоё.\n\n— К.",repeatable:!1,weight:2,goal:{type:"craft",blueprintId:"slots",requireBlueprint:!0,recipe:{coins:80,items:[{id:"plank",count:8},{id:"rope",count:4}]}},reward:{type:"island",blueprintId:"slots"}},{id:"collect-planks",title:"Запас досок",description:"Море подтачивает берег. Натащи досок — без них нам не сколотить даже жалкий плот.\n\n— К.",repeatable:!0,weight:1,goal:{type:"collect",itemId:"plank",count:8},reward:{type:"coins",amount:20},modifiers:[{type:"itemSpawn",itemId:"plank",chance:.22,from:0}]},{id:"collect-compass",title:"Счастливый компас",description:"У чаек в когтях видели блеск. Достань компас — говорят, он не даёт сбиться в шторм.\n\n— К.",repeatable:!1,weight:1,goal:{type:"collect",itemId:"lucky-compass",count:1,questItem:!0},reward:{type:"coins",amount:25},modifiers:[{type:"itemSpawn",itemId:"lucky-compass",chance:.14,from:0,questItem:!0}]},{id:"height-surge",title:"Гонка с приливом",description:"Вода сегодня злая. Поднимись повыше, пока она не накрыла остров.\n\n— К.",repeatable:!0,weight:1,goal:{type:"height",height:12,time:50},reward:{type:"coins",amount:30},modifiers:[{type:"waterSpeed",mul:3.5}]},{id:"craft-raft",title:"Сколотить плот",description:"В бутылке чертёж плота. Собери доски и верёвки и сколоти его — на острове его не будет, но он нам ещё пригодится.\n\n— К.",repeatable:!1,weight:1,goal:{type:"craft",placeOnIsland:!1,recipe:{coins:0,items:[{id:"plank",count:6},{id:"rope",count:3}]}},reward:{type:"coins",amount:40}},{id:"rum-streak",title:"Три глотка",description:"Старый пират писал: пролети на роме три раза подряд — тогда море тебя заметит.\n\n— К.",repeatable:!0,weight:1,goal:{type:"action",action:"rum_streak",count:3},reward:{type:"coins",amount:15},modifiers:[{type:"bonusSpawn",bonusId:"rum",chance:.28}]}]})}}}));

